class Solution {
public:
    vector<int> findPeakGrid(vector<vector<int>>& mat) {
        int m = mat.size();
        int n = mat[0].size();
        int lo = 0, hi = m - 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            int maxCol = 0;
            for (int j = 1; j < n; j++) {
                if (mat[mid][j] > mat[mid][maxCol]) {
                    maxCol = j;
                }
            }
            int topVal = (mid > 0) ? mat[mid - 1][maxCol] : -1;
            int bottomVal = (mid < m - 1) ? mat[mid + 1][maxCol] : -1;
            if (mat[mid][maxCol] > topVal && mat[mid][maxCol] > bottomVal) {
                return {mid, maxCol};
            } else if (topVal > mat[mid][maxCol]) {
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }
        return {-1, -1};
    }
};
